#import <Foundation/Foundation.h>
#import <CoreServices/CoreServices.h>   // FSEvents
#import <IOKit/pwr_mgmt/IOPMLPower.h> // optional shutdown handling
#import <unistd.h>                     // sleep

// -----------------------------------------------------------------------------
// Configuration – change ONE line to point to the file you care about.
// -----------------------------------------------------------------------------
static const char *kPathToWatch = "/path/to/your/critical/file.db";

// -----------------------------------------------------------------------------
// Logging – all messages go to system.log (easy to correlate with launchd)
// -----------------------------------------------------------------------------
static void LOG(const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    char buf[1024];
    vsnprintf(buf, sizeof(buf), fmt, args);
    va_end(args);
    [[NSFileHandle fileHandleWithStandardOutput] writeData:[buf dataUsingEncoding:NSUTF8StringEncoding]];
    // also send to syslog
    syslog(LOG_INFO, "%s", buf);
}

// -----------------------------------------------------------------------------
// Helper – obtain a CFString for the file we watch (FSEvents wants a directory)
// -----------------------------------------------------------------------------
static CFStringRef GetVNodeString(CFStringRef path) {
    // FSEvents expects a directory, not a file.  We watch the parent folder.
    NSArray<NSString *> *components = [NSString.alloc initWithUTF8String:path].pathComponents;
    [components removeLastObject]; // drop the filename
    NSString *dir = [NSString pathWithComponents:components];
    CFRetain((CFStringRef)dir);
    return (CFStringRef)dir; // retain count is balanced by CFRelease caller
}

// -----------------------------------------------------------------------------
// Callback – invoked by the run‑loop whenever the file changes
// -----------------------------------------------------------------------------
static void EventStreamCallback(ConstFSEventStreamRef streamRef,
                                void *info,
                                size_t numEvents,
                                const void *eventPaths,
                                const FSEventStreamEventFlags flags[],
                                const FSEventStreamEventId eventIds[])
{
    // Defensive: ignore spurious “no‑event” calls.
    if (numEvents == 0) return;

    for (size_t i = 0; i < numEvents; ++i) {
        const char *changedPath = (const char *)CFStringGetCStringPtr((CFStringRef)eventPaths[i]);
        if (!changedPath) {
            // Fallback – we must copy to a CString buffer.
            CFStringGetCString((CFStringRef)eventPaths[i], (char *)&changedPath, 1024, kCFStringEncodingUTF8);
        }

        // Build full path (the event gives us the *directory* which may be a parent)
        NSString *fullPath = [NSString stringWithFormat:@"%s/%s", kPathToWatch, changedPath];
        const char *fullCPath = [fullPath fileSystemRepresentation];

        // Log the change, together with flags for debugging
        LOG("📂 Change detected at %s (flags: 0x%X)", fullCPath, (unsigned int)flags[i]);

        // ---- Your defensive‑programming hook point -------------------------------------------------
        // Here you would:
        //   • Verify the file still exists (`[[NSFileManager defaultManager] fileExistsAtPath:…]`)
        //   • Validate its integrity (checksum, header, version)
        //   • If OK, push an update to your DB backend (e.g. CoreData, SQL, external service)
        //   • If NOT OK, trigger a rollback / alert.
        // For demonstration we just print a message.
        // -------------------------------------------------------------------------------------------
        // Example of a simple defensive check:
        if (flags[i] & kFSEventsFlagMustVerify) {
            LOG("⚠️  Event flagged as MustVerify – performing manual sanity check.");
        }

        // You could also fire an NSWorkspace notification, send to a local Unix socket, etc.
    }
}

// -----------------------------------------------------------------------------
// Main – global init / cleanup – designed to be robust enough for launchd.
// -----------------------------------------------------------------------------
int main(int argc, const char * argv[]) {
    // --- Defensive entry point ----------------------------------------------------
    @autoreleasepool {
        // 1️⃣ Validate the path early – fail fast.
        if (!access(kPathToWatch, F_OK)) {
            LOG("🔍 Watching file exists: %s", kPathToWatch);
        } else {
            LOG("❌ ERROR – required file %s does NOT exist. Exiting.", kPathToWatch);
            return 1;
        }

        // 2️⃣ Determine the *directory* that contains the file (FSEvents works on dirs)
        NSString *dirPath = [NSString stringWithUTF8String:kPathToWatch];
        NSString *parentDir = [dirPath stringByDeletingLastPathComponent];
        CFStringRef vnode = (CFStringRef)parentDir;
        CFRetain(vnode); // keep it alive for the lifetime of the stream

        // 3️⃣ Build the options dictionary – make it tolerant of suspend/resume.
        FSEventStreamContext ctx = {0, NULL, NULL, NULL, NULL};
        CFOptionFlags flags = kFSEventsApiVersionSupportsExtendedFlags |
                              kFSEventStreamCreateFlagFileEvents |
                              kFSEventStreamCreateFlagWatchFSNotifyFlags |
                              kFSEventStreamCreateFlagNoDefer;

        // 4️⃣ Create the stream
        ConstFSEventStreamRef stream = FSEventStreamCreate(
            kCFAllocatorDefault,
            (CFStringRef)vnode,               // the directory
            &flags,
            &ctx,
            EventStreamCallback,
            NULL
        );

        if (!stream) {
            LOG("❌ Failed to create FSEvent stream – aborting.");
            return 1;
        }

        // 5️⃣ Run the stream in a background run‑loop (very lightweight)
        LOG("✅ FileWatcher daemon started – monitoring %s", kPathToWatch);
        CFRunLoopRun();   // ← blocks forever; launchd will restart if SIGTERM is send

        // The stream is automatically released when the process exits.
    }
    return 0; // never reached
}
```

