## 3️⃣ Minimal Bootstrap Server (Node.js)

> The server below is **only for demonstration**. In production you’d probably use HTTPS, authentication, rate‑limiting, DDoS protection, etc.

```javascript
// server.js
// ---------------------------------------------------------------
// Tiny WebSocket signalling server (Node + ws)
// ---------------------------------------------------------------
const express = require('express');
const http = require('http');
const WebSocket = require('ws');

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ noServer: true });

// Serve static files (HTML + client.js) if you like
app.use(express.static('public'));

// ---- WebSocket upgrade -------------------------------------------------
server.on('upgrade', (req, socket, head) => {
  wss.handleUpgrade(req, socket, head, (ws) => {
    wss.emit('connection', ws, req);
  });
});

server.listen(8080, () => console.log('Server listening on http://localhost:8080'));

// ---- Signalling logic --------------------------------------------------
wss.on('connection', (ws) => {
  console.log('New client connected');

  ws.on('message', (msg) => {
    // Expect JSON: {type:"offer"| "answer", sdp:string, from:string}
    let data;
    try { data = JSON.parse(msg); } catch (e) { return; }

    if (data.type === 'offer' || data.type === 'answer') {
      // broadcast to every other client (including the original sender if you want echo‑back)
      wss.clients.forEach(client => {
        if (client !== ws && client.readyState === WebSocket.OPEN) {
          client.send(msg);
        }
      });
    } else if (data.type === 'candidate') {
      // ICE candidate
      wss.clients.forEach(client => {
        if (client !== ws && client.readyState === WebSocket.OPEN) {
          client.send(msg);
        }
      });
    }
  });

  ws.on('close', () => console.log('Client disconnected'));
});
```

*Run*: `node server.js` → Open `http://localhost:8080` in two different tabs/browsers.

