### 4.2 Client Logic (`public/client.js`)

```javascript
/*********************************************************************
 *  WebRTC P2P Demo – No TURN relay, pure P2P after signalling
 *
 *  Two peers (A & B) can be opened in the same browser (different tabs)
 *  or in completely separate devices. The only external hop is the
 *  tiny WebSocket signalling server shown earlier.
 *
 *  – Core concepts explained inline.
 *********************************************************************/

(async () => {
  // --------------------------------------------------------------
  // 0️⃣ Utility helpers
  // --------------------------------------------------------------
  const logEl = document.getElementById('log');
  const myId = `Peer-${crypto.randomUUID().slice(0, 8)}`; // simple random ID
  document.getElementById('myId').textContent = myId;

  function log(msg) {
    const time = new Date().toLocaleTimeString();
    logEl.textContent += `[${time}] ${msg}\n`;
    logEl.scrollTop = logEl.scrollHeight;
  }

  // --------------------------------------------------------------
  // 1️⃣ Open WebSocket to the signalling server
  // --------------------------------------------------------------
  const ws = new WebSocket(`ws://${location.host}`);
  ws.addEventListener('open', () => log('WebSocket connected'));

  ws.addEventListener('message', (ev) => {
    try {
      const payload = JSON.parse(ev.data);
      if (payload.type === 'offer') handleRemoteOffer(payload);
      else if (payload.type === 'answer') handleRemoteAnswer(payload);
      else if (payload.type === 'candidate') handleIceCandidate(payload);
    } catch (_) { /* ignore non‑JSON */ }
  });

  // --------------------------------------------------------------
  // 2️⃣ Initialise RTCPeerConnection
  // --------------------------------------------------------------
  const pc = new RTCPeerConnection({
    iceServers: [] // we do NOT use TURN – pure P2P via ICE/STUN only
  });

  pc.addEventListener('icecandidate', (event) => {
    if (!event.candidate) return; // end of candidates
    const cand = {
      type: 'candidate',
      sdpMLineIndex: event.candidate.sdpMLineIndex,
      sdpMid: event.candidate.sdpMid,
      candidate: event.candidate.candidate
    };
    ws.send(JSON.stringify(cand));
    log(`→ ICE candidate sent`);
  });

  pc.addEventListener('datachannel', (event) => {
    if (!dataChannel) {
      dataChannel = event.channel;
      initDataChannelHandlers();
    }
  });

  // --------------------------------------------------------------
  // 3️⃣ UI / Interaction helpers
  // --------------------------------------------------------------
  let dataChannel = null;

  function initDataChannelHandlers() {
    document.getElementById('sendBtn').disabled = false;
    document.getElementById('msgInput').disabled = false;

    dataChannel.addEventListener('open', () => {
      log('🔗 DataChannel opened (reliable, ordered)');
    });

    dataChannel.addEventListener('message', (ev) => {
      log('← Received: ' + ev.data);
    });

    dataChannel.addEventListener('close', () => log('❌ DataChannel closed'));
    dataChannel.addEventListener('error', (err) => log('⚠️ DataChannel error: ' + err));

    // UI sender
    document.getElementById('sendBtn').onclick = () => {
      const txt = document.getElementById('msgInput').value;
      if (txt) {
        dataChannel.send(txt);
        log('→ Sent: ' + txt);
        document.getElementById('msgInput').value = '';
      }
    };
  }

  // --------------------------------------------------------------
  // 4️⃣ Peer‑specific behaviours (A initiates, B waits)
  // --------------------------------------------------------------
  const isPeerA = location.search.includes('peer=a');
  const isPeerB = location.search.includes('peer=b');
  if (!isPeerA && !isPeerB) {
    alert('Open two windows/tabs: ?peer=a and ?peer=b');
  }

  function startConnection() {
    // Create a reliable, ordered data channel (default)
    dataChannel = pc.createDataChannel('chat', { ordered: true, maxRetransmits: 0 });
    initDataChannelHandlers();
  }

  // --------------------------------------------------------------
  // 5️⃣ Signalling helpers
  // --------------------------------------------------------------
  function handleRemoteOffer(msg) {
    if (!isPeerB) return; // only Peer B should answer
    log('← Remote offer received');
    pc.setRemoteDescription(new RTCSessionDescription(msg))
      .then(() => pc.createAnswer())
      .then(answer => {
        answer.sdp = maybePreferIceUDP(answer.sdp); // optional tweak
        return pc.setLocalDescription(answer);
      })
      .then(() => {
        const payload = {
          type: 'answer',
          sdp: pc.localDescription.sdp,
          from: myId
        };
        ws.send(JSON.stringify(payload));
        log('→ Answer sent');
      })
      .catch(err => log('❌ Error creating answer: ' + err));
  }

  function handleRemoteAnswer(msg) {
    if (!isPeerA) return;
    log('← Remote answer received');
    pc.setRemoteDescription(new RTCSessionDescription(msg))
      .catch(err => log('❌ Error setting remote answer: ' + err));
  }

  function handleIceCandidate(msg) {
    pc.addIceCandidate(new RTCIceCandidate(msg))
      .catch(err => log('❌ ICE candidate error: ' + err));
    log(`→ ICE candidate added`);
  }

  function maybePreferIceUDP(sdp) {
    // Some browsers prefer UDP for ICE; forcing it can reduce latency.
    // This is optional; many devices already do it automatically.
    return sdp.replace(/a=ice-options:.*\r\n/g, '').replace(/ udp /g, ' UDP ');
  }

  // --------------------------------------------------------------
  // 6️⃣ Kick‑off workflow
  // --------------------------------------------------------------
  if (isPeerA) {
    // Peer A initiates when user clicks "Connect"
    document.getElementById('connectBtn').onclick = () => {
      startConnection();

      pc.createOffer()
        .then(offer => {
          offer.sdp = maybePreferIceUDP(offer.sdp);
          return pc.setLocalDescription(offer);
        })
        .then(() => {
          const payload = {
            type: 'offer',
            sdp: pc.localDescription.sdp,
            from: myId
          };
          ws.send(JSON.stringify(payload));
          log('→ Offer created & sent');
        })
        .catch(err => log('❌ Offer error: ' + err));
    };
  }
})();
```

**How to run the demo**

1. Start the Node server (`node server.js`).  
2. Open two **different tabs** of `http://localhost:8080/peer=a` and `http://localhost:8080/peer=b`.  
3. In the *Peer A* tab press **Connect**.  
4. The *Peer B* tab will automatically receive the offer and respond. Once the data channel is ready, you can type messages in either side and see them appear instantly—**without any further traffic to the server**.

